<script setup>
import {ref,onMounted,onUnmounted} from 'vue'
import {adminEbook,downloadOriginal,viewerURL} from './admin-ebook.js'
import {adminDate,adminRoute} from './admin-navigation.js'
const rows=ref([]),total=ref(0),page=ref(0),search=ref(''),state=ref(''),publication=ref(''),deleted=ref('active'),selected=ref(null),message=ref(''),busy=ref(false),loaded=ref(false),operation=ref(''),reason=ref(''),confirmed=ref(false)
const states={uploading:'업로드 중',queued:'변환 대기',processing:'변환 중',review:'검토 대기',ready:'이용 가능',failed:'실패',archived:'보관'}
const actions={retry:'재처리',suspend:'게시 중지',resume:'게시 재개',delete:'삭제',restore:'복원',approve:'검토 승인'}
const impact={retry:'원본으로 다시 변환하며 기존 공유는 해제됩니다. 결과를 검토한 뒤 게시해야 합니다.',suspend:'회원과 공유 링크의 열람·다운로드를 차단하고 진행 중인 변환은 중단합니다.',resume:'현재 회원·공유 권한에 따라 다시 열람할 수 있게 합니다.',delete:'회원 목록과 공유 접근을 차단합니다. 파일은 보존하며 관리자만 복원할 수 있습니다.',restore:'게시 중지 상태로 복원합니다. 이전 공유 링크는 복구하지 않습니다.',approve:'변환 결과를 검토 완료로 기록합니다. 게시 중지 상태는 별도로 재개해야 합니다.'}
let epoch=0,detailEpoch=0,disposed=false
const size=n=>new Intl.NumberFormat('ko-KR',{maximumFractionDigits:1}).format(n/1048576)+' MiB'
async function load(){const id=++epoch;busy.value=true;try{const data=await adminEbook('admin_list',{search:search.value,state:state.value,publication:publication.value,deleted:deleted.value,offset:page.value*50});if(disposed||id!==epoch)return;rows.value=data.books;total.value=data.total;loaded.value=true;message.value=''}catch(e){if(id===epoch&&!disposed){rows.value=[];loaded.value=false;message.value='목록 확인 실패: '+e.message}}finally{if(id===epoch&&!disposed)busy.value=false}}
function syncRoute(){const q=adminRoute(location.hash).query;search.value=q.get('search')||'';state.value=q.get('state')||'';publication.value=q.get('publication')||'';deleted.value=q.get('deleted')||'active';page.value=Math.max(0,Number(q.get('page'))||0);selected.value=null;++detailEpoch;operation.value='';load()}
function navigate(nextPage=0){const q=new URLSearchParams();for(const [k,v] of Object.entries({search:search.value,state:state.value,publication:publication.value,deleted:deleted.value,page:nextPage?String(nextPage):''}))if(v)q.set(k,v);const next='#ebooks'+(q.size?'?'+q:'');if(location.hash===next)syncRoute();else location.hash=next}
async function open(row){const id=++detailEpoch;selected.value=null;operation.value='';try{const data=await adminEbook('admin_detail',{book_id:row.id});if(!disposed&&id===detailEpoch)selected.value=data}catch(e){if(!disposed&&id===detailEpoch)message.value=e.message}}
function begin(action){operation.value=action;reason.value='';confirmed.value=false}
async function execute(){if(busy.value||!selected.value||!operation.value||!reason.value.trim()||!confirmed.value)return;busy.value=true;try{const data=await adminEbook('admin_'+operation.value,{book_id:selected.value.id,reason:reason.value.trim(),expected_updated_at:selected.value.updated_at});operation.value='';await load();await open(data);message.value='관리 조치를 기록했습니다.'}catch(e){message.value=e.message}finally{busy.value=false}}
async function download(a){busy.value=true;try{await downloadOriginal(selected.value,a)}catch(e){message.value=e.message}finally{busy.value=false}}
onMounted(()=>{syncRoute();window.addEventListener('hashchange',syncRoute);window.addEventListener('popstate',syncRoute)})
onUnmounted(()=>{disposed=true;++epoch;++detailEpoch;window.removeEventListener('hashchange',syncRoute);window.removeEventListener('popstate',syncRoute)})
</script>
<template><main class="member-page admin-ebooks"><h1>이북 서비스 현황</h1><p>회원이 등록한 원본과 이북, 처리 상태를 확인하고 서비스 운영 조치를 수행합니다.</p><form class="ebook-filters" @submit.prevent="navigate(0)"><label>검색<input v-model="search" placeholder="회원명·이메일·제목·파일명" maxlength="200"></label><label>처리 상태<select v-model="state"><option value="">전체</option><option v-for="(label,key) in states" :key="key" :value="key">{{label}}</option></select></label><label>게시 상태<select v-model="publication"><option value="">전체</option><option value="active">중지 아님</option><option value="suspended">게시 중지</option></select></label><label>삭제 여부<select v-model="deleted"><option value="active">삭제 제외</option><option value="deleted">삭제됨</option><option value="all">전체</option></select></label><button class="member-button" :disabled="busy">검색·새로고침</button></form><p role="status" aria-live="polite">{{busy?'처리 중…':message}}</p><p v-if="!loaded&&!busy"><button @click="load">다시 확인</button></p><div v-if="loaded" class="ebook-table-scroll"><table><caption>이북 {{total}}건 · {{page+1}}페이지 · 페이지당 50건</caption><thead><tr><th>회원</th><th>이북·원본</th><th>용량·페이지</th><th>처리·게시</th><th>등록·수정(KST)</th><th>상세</th></tr></thead><tbody><tr v-for="b in rows" :key="b.id"><td>{{b.owner_name||'이름 미등록'}}<small>{{b.owner_email}}</small></td><td>{{b.title}}<small>{{b.filename}} · {{b.format.toUpperCase()}}</small></td><td>{{size(b.source_bytes)}}<small>{{b.pages??'—'}}페이지</small></td><td>{{states[b.state]}}<small>{{b.deleted_at?'삭제됨':b.publication_suspended?'게시 중지':'중지 아님'}}</small></td><td>{{adminDate(b.created_at)}}<small>{{adminDate(b.updated_at)}}</small></td><td><button class="member-button" :disabled="busy" @click="open(b)">상세 보기</button></td></tr><tr v-if="!rows.length"><td colspan="6">조건에 맞는 이북이 없습니다.</td></tr></tbody></table></div><div class="ebook-actions"><button :disabled="busy||page===0" @click="navigate(page-1)">이전</button><button :disabled="busy||!loaded||(page+1)*50>=total" @click="navigate(page+1)">다음</button></div>
<section v-if="selected" class="ebook-admin-detail" aria-label="이북 상세"><h2>{{selected.title}}</h2><p>{{selected.owner_name}} · {{selected.owner_email}}</p><p>{{selected.filename}} · {{size(selected.source_bytes)}} · {{states[selected.state]}}</p><div class="ebook-actions"><a v-if="['ready','review'].includes(selected.state)" class="member-button" :href="viewerURL(selected.id)" target="_blank" rel="noopener">이북 페이지 열기 ↗</a><button v-for="a in selected.assets.filter(a=>a.kind==='source')" :key="a.id" :disabled="busy" @click="download(a)">원본 다운로드</button></div><h3>처리 안내·오류</h3><ul v-if="selected.warnings?.length"><li v-for="(w,i) in selected.warnings" :key="i">{{w}}</li></ul><p v-else>기록된 오류가 없습니다.</p><div class="ebook-actions"><button v-if="!selected.deleted_at&&selected.state==='review'" :disabled="busy" @click="begin('approve')">검토 승인</button><button v-if="!selected.deleted_at&&selected.state==='failed'" :disabled="busy" @click="begin('retry')">재처리</button><button v-if="!selected.deleted_at&&selected.state!=='archived'&&!selected.publication_suspended" :disabled="busy" @click="begin('suspend')">게시 중지</button><button v-if="!selected.deleted_at&&selected.state==='ready'&&selected.publication_suspended" :disabled="busy" @click="begin('resume')">게시 재개</button><button v-if="!selected.deleted_at" :disabled="busy" @click="begin('delete')">삭제</button><button v-else :disabled="busy" @click="begin('restore')">복원</button></div>
<form v-if="operation" class="ebook-operation" @submit.prevent="execute"><h3>{{actions[operation]}} 확인</h3><p>대상: {{selected.title}} · {{selected.filename}}</p><p>{{impact[operation]}}</p><label>조치 사유<textarea v-model="reason" required maxlength="1000" rows="3"></textarea></label><label class="ebook-confirm"><input v-model="confirmed" type="checkbox" required>대상과 영향을 확인했습니다.</label><div class="ebook-actions"><button :disabled="busy||!confirmed||!reason.trim()">{{actions[operation]}} 실행</button><button type="button" :disabled="busy" @click="operation=''">취소</button></div></form><h3>처리·관리 이력</h3><ol><li v-for="a in selected.audit" :key="a.id">{{adminDate(a.created_at)}} · {{a.action}} · {{a.actor_id||'변환 시스템'}}<p v-if="a.reason">{{a.reason}}</p><p v-if="a.before_state">{{a.before_state.state}} → {{a.after_state?.state}} · 게시 중지 {{a.before_state.suspended?'예':'아니요'}} → {{a.after_state?.suspended?'예':'아니요'}}</p></li></ol></section></main></template>
<style scoped>.ebook-filters{display:flex;gap:14px;align-items:end;flex-wrap:wrap;margin:24px 0}.ebook-filters label{display:grid;gap:7px}.ebook-filters label:first-child{flex:1;min-width:210px}.ebook-filters input,.ebook-filters select,.ebook-operation textarea{border:1px solid #b5c5d5;border-radius:6px;padding:10px;background:white;color:#16334f;max-width:100%}.ebook-table-scroll{overflow:auto;max-width:100%}.admin-ebooks table{min-width:900px;width:100%;border-collapse:collapse;text-align:left}.admin-ebooks caption{text-align:left;padding:12px 0}.admin-ebooks td,.admin-ebooks th{padding:14px 12px;border-bottom:1px solid #d5e0eb;vertical-align:top;overflow-wrap:anywhere;max-width:260px}.admin-ebooks th{background:#eef4fc}.admin-ebooks small{display:block;color:#596f85;margin-top:6px}.ebook-actions{display:flex;gap:12px;flex-wrap:wrap;margin:18px 0}.admin-ebooks button,.ebook-actions a{border:1px solid #b5c5d5;border-radius:6px;padding:10px 14px;background:#edf3fa;font-weight:600}.admin-ebooks button:disabled{opacity:.5}.ebook-admin-detail{border:1px solid #d5e0eb;border-radius:12px;padding:24px;margin:28px 0;overflow-wrap:anywhere}.ebook-admin-detail h2{font-size:24px;font-weight:750}.ebook-admin-detail h3{font-size:18px;font-weight:700;margin:24px 0 12px}.ebook-admin-detail li{padding:12px 0;border-bottom:1px solid #e3eaf2}.ebook-operation{border:1px solid #e3c788;background:#fffbf0;padding:20px;border-radius:8px}.ebook-operation label{display:grid;gap:8px;margin:14px 0}.ebook-operation .ebook-confirm{display:flex;align-items:center;gap:10px}.ebook-confirm input{width:20px;height:20px}.ebook-operation textarea{width:100%}</style>
